{
  "steps": [
    {
      "action": "Inventory the target binary's format, architecture, entrypoints, sections, imports, exports, symbols, strings, protections, and analysis blockers, and record any missing or malformed inputs as incomplete before proceeding to deeper static analysis.",
      "technique": "RE-BINARY-INVENTORY",
      "deterministic_check": "The analyzed artifact hash matches campaign metadata; binary format and architecture are recorded; expected inventory artifacts exist and parse successfully; and any missing or malformed inputs are reported as incomplete rather than treated as absence."
    },
    {
      "action": "Map static call relationships around the input surface by identifying entrypoints, callers, callees, indirect-call uncertainty, and data-flow-relevant helpers associated with the target input-validation behavior.",
      "technique": "RE-STATIC-CALLGRAPH",
      "deterministic_check": "Every claimed call edge has an address or symbol locator; unresolved indirect calls are listed explicitly; and the call graph identifies which paths are proven and which remain candidates."
    },
    {
      "action": "Trace input acquisition through parsing, transformations, comparisons, branch decisions, success paths, and rejection paths to recover the validation logic and document the accepted input, without inferring semantics from strings alone.",
      "technique": "RE-INPUT-VALIDATION-TRACE",
      "deterministic_check": "The input source and destination representation are identified; every success and rejection branch has a code locator; transformations and comparison constants are supported by decompilation or disassembly evidence; and unknown helper behavior is represented as an unresolved dependency."
    }
  ]
}
